// generated by scripts/build.js – 301 legacy hosts to https://fileopia.com
const L=["freepdf-tools-9u1.pages.dev","www.fileopia.com"];
export async function onRequest(ctx){const u=new URL(ctx.request.url);if(u.protocol==='http:'||L.some(h=>u.host===h||u.host.endsWith('.'+h)))return Response.redirect('https://fileopia.com'+u.pathname+u.search,301);return ctx.next();}
